import React from 'react';
import './Ended.css'; // Ujistěte se, že máte tento soubor pro stylování komponenty
import './App'; // Ujistěte se, že máte tento soubor pro stylování komponenty

const Ended = ({ score, houseLength, onReturnToApp, onNewGame }) => {
  const handleReturnToMainScreen = () => {
    console.log("Returning to the main screen Board...");
    setGameEnded(false);
    setGameData(null);
    // Logika pro návrat na hlavní obrazovku (např. resetování stavu)
  };

  return (
    <div className="ended">
      <h2>Game Over!</h2>
      <div className="scoreboard">
        <h3>Final Scores:</h3>
        <ul>
          {score.map((playerScore, index) => (
            <li key={index}>
              Player {playerScore.playerId}: {playerScore.value}/{houseLength}
            </li>
          ))}
        </ul>
      </div>
      <div className="buttons">
        <button onClick={onNewGame}>New Game</button> {/* Tlačítko pro novou hru */}
        <button
  onClick={() => {
    console.log("Return to Main Screen clicked");
    onReturnToApp();
  }}
>
  Return to Main Screen
</button>     </div>
    </div>
  );
};

export default Ended;
